import{_ as e,o as t,c as r,a6 as l}from"./chunks/framework.BBIckNDn.js";const p=JSON.parse('{"title":"読み進め方","description":"","frontmatter":{"title":"読み進め方","study":{"source":"統合ガイド","kind":"統合ガイド","status":"初版","domain":"guide","generated":true,"catalog":true,"summary":"辞典を最初から順番に読む必要はありません。いま持っている疑問を、関係する項目へつなげる読み順です。"}},"headers":[],"relativePath":"guide/learning-paths.md","filePath":"guide/learning-paths.md"}'),i={name:"guide/learning-paths.md"};function o(s,a,h,d,n,u){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="読み進め方" tabindex="-1">読み進め方 <a class="header-anchor" href="#読み進め方" aria-label="Permalink to &quot;読み進め方&quot;">​</a></h1><p>辞典を最初から順番に読む必要はありません。いま持っている疑問を、関係する項目へつなげる読み順です。</p><h2 id="「確保する」と内部で何が起きるか" tabindex="-1">「確保する」と内部で何が起きるか <a class="header-anchor" href="#「確保する」と内部で何が起きるか" aria-label="Permalink to &quot;「確保する」と内部で何が起きるか&quot;">​</a></h2><ol><li><a href="/study/runtime/memory/storage-duration-and-lifetime.html">所有・記憶域・寿命</a>を区別する。</li><li><a href="/study/runtime/memory/allocators-and-pools.html">アロケータ</a>で、小さい領域の再利用とOSへの追加要求を調べる。</li><li><a href="/study/os/">OS</a>の仮想メモリ、ページフォルト、物理ページとの関係へ進む。</li><li><a href="/study/tools/">調査ツール</a>で、確保量・常駐量・解放と再利用を観察する。</li></ol><h2 id="ソースコードがcpuで動くまで" tabindex="-1">ソースコードがCPUで動くまで <a class="header-anchor" href="#ソースコードがcpuで動くまで" aria-label="Permalink to &quot;ソースコードがCPUで動くまで&quot;">​</a></h2><ol><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a>から、コンパイルとリンクをたどる。</li><li><a href="/study/compilers/">コンパイラ</a>と<a href="/study/languages/">言語</a>から、型・ABI・実行方式を調べる。</li><li><a href="/study/hardware/">ハードウェア</a>の命令、レジスタ、キャッシュへつなぐ。</li></ol><h2 id="入力からゲーム画面まで" tabindex="-1">入力からゲーム画面まで <a class="header-anchor" href="#入力からゲーム画面まで" aria-label="Permalink to &quot;入力からゲーム画面まで&quot;">​</a></h2><ol><li><a href="/study/game/patterns/game-loop-and-update.html">ゲームループ</a>で入力・更新・描画の時間を分ける。</li><li><a href="/study/game/ecs.html">ECS</a>でID、データ配置、Query、構成変更を調べる。</li><li><a href="/study/math/">数学</a>と<a href="/study/graphics/">グラフィックス</a>から座標・GPU・表示へ進む。</li><li><a href="/study/guide/low-level/debugging-and-profiling.html">計測</a>で、CPU・GPU・待機・確保のどこが重いか確かめる。</li></ol><p>まとまった実装を追うなら、<a href="/study/game/shooter-design.html">小さなシューティングの設計</a>から<a href="/study/game/shooter-cpp.html">C++版</a>と<a href="/study/game/shooter-unity.html">Unity版</a>へ進めます。仕様・データ・更新順を対応させて読みます。</p><h2 id="urlを開いてからページが見えるまで" tabindex="-1">URLを開いてからページが見えるまで <a class="header-anchor" href="#urlを開いてからページが見えるまで" aria-label="Permalink to &quot;URLを開いてからページが見えるまで&quot;">​</a></h2><p><a href="/study/network/">ネットワーク</a>のDNS・接続・HTTPから、<a href="/study/browser/">ブラウザ</a>の解析・実行・描画へ進む系列です。この系列は現在、基礎本文を充実させる段階で、分野索引に項目を整理しています。</p><h2 id="作り方の変化を歴史から見る" tabindex="-1">作り方の変化を歴史から見る <a class="header-anchor" href="#作り方の変化を歴史から見る" aria-label="Permalink to &quot;作り方の変化を歴史から見る&quot;">​</a></h2><p><a href="/study/history/video-games.html">ビデオゲーム史</a>で作品・ハード・媒体・流通を並べ、気になった時代からメモリ、描画、入力、通信の各論へ進めます。年別の表は地域・初公開・発売を区別して読みます。</p>',13)])])}const c=e(i,[["render",o]]);export{p as __pageData,c as default};
